sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return;
    }

    // If completed is checked → set actual completion date to today's date
    if (newValue == 'true') {
        var today = new Date();

        function pad(n) {
            return n < 10 ? '0' + n : n;
        }

        var year = today.getFullYear();
        var month = pad(today.getMonth() + 1); // months are 0-based
        var day = pad(today.getDate());

        var formattedDate = year + '-' + month + '-' + day;

        g_form.setValue('actual_completion_date', formattedDate);
    }

    // If completed is unchecked → clear the actual completion date
    if (newValue == 'false') {
        g_form.setValue('actual_completion_date', '');
    }
}
